def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """
    Check if any two numbers in the list are closer than the given threshold.

    >>> has_close_elements([1.0, 2.0, 3.0], 0.5)
    False
    >>> has_close_elements([1.0, 2.8, 3.0, 4.0, 5.0, 2.0], 0.3)
    True
    """
    # Validate input types
    if not isinstance(threshold, (int, float)):
        raise TypeError("Threshold must be a numeric type.")
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("Numbers must be a list or tuple of numeric values.")

    for idx, num in enumerate(numbers):
        if not isinstance(num, (int, float)):
            raise TypeError(f"Element at index {idx} ({num}) is not a number.")

    # Not enough elements to compare
    if len(numbers) < 2:
        return False

    # Sort the numbers so that the closest pairs are adjacent
    sorted_numbers = sorted(numbers)

    # Check adjacent differences
    for i in range(1, len(sorted_numbers)):
        if abs(sorted_numbers[i] - sorted_numbers[i - 1]) < threshold:
            return True
    return False

