    lds = [1] * n
    for i in range(n-1, -1, -1):
        for j in range(i+1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1
    # Maximum length of bitonic subsequence
    max_len = 0
    for i in range(n):
        # peak at i
        current = lis[i] + lds[i] - 1
        if current > max_len:
            max_len = current
    return n - max_len
